const reverseLookup = Object.fromEntries(
  Object.entries(FIXED_INTERFACE_TRANSLATIONS).map(([language, dictionary]) => [
    language,
    Object.fromEntries(Object.entries(dictionary).map(([source, translation]) => [translation, source])),
  ]),
) as Record<SystemLanguage, Record<string, string>>;

const allLanguageReverseLookup = Object.assign({}, ...Object.values(reverseLookup));

export function fixedInterfaceSource(language: SystemLanguage, visibleText: string): string {
  return reverseLookup[language][visibleText] || allLanguageReverseLookup[visibleText] || visibleText;
}

export function translateFixedInterfaceText(language: SystemLanguage, visibleText: string): string {
  const source = fixedInterfaceSource(language, visibleText);
  return FIXED_INTERFACE_TRANSLATIONS[language][source] || source;
}
